import{_ as a,o as t,c as n,a2 as s}from"./chunks/framework.BXzK3EA4.js";const m=JSON.parse('{"title":"The Problem","description":"","frontmatter":{},"headers":[],"relativePath":"concepts/problem-statement.md","filePath":"concepts/problem-statement.md","lastUpdated":null}'),i={name:"concepts/problem-statement.md"};function r(o,e,l,p,c,h){return t(),n("div",null,[...e[0]||(e[0]=[s(`<h1 id="the-problem" tabindex="-1">The Problem <a class="header-anchor" href="#the-problem" aria-label="Permalink to &quot;The Problem&quot;">​</a></h1><h2 id="electronic-support-receivers" tabindex="-1">Electronic Support receivers <a class="header-anchor" href="#electronic-support-receivers" aria-label="Permalink to &quot;Electronic Support receivers&quot;">​</a></h2><p>An Electronic Support (ES) receiver is a <strong>passive</strong> sensor — it only listens. It never transmits. Its job is to detect, intercept, and analyse radio frequency emissions from hostile sources.</p><p>The critical constraint: <strong>an ES receiver can listen to only one narrow frequency band at a time</strong> while remaining responsible for monitoring a much wider spectrum.</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Hostile radar (EMITTER)     →  transmits RF pulses</span></span>
<span class="line"><span>                                   ↓</span></span>
<span class="line"><span>ASTRA&#39;s ES receiver (SENSOR) →  listens, intercepts, identifies</span></span>
<span class="line"><span>                                   ↓</span></span>
<span class="line"><span>ASTRA&#39;s scheduler (BRAIN)   →  decides WHICH band to listen to, WHEN</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><h2 id="the-two-dimensional-search" tabindex="-1">The two-dimensional search <a class="header-anchor" href="#the-two-dimensional-search" aria-label="Permalink to &quot;The two-dimensional search&quot;">​</a></h2><p>Interception is a <strong>two-dimensional search problem</strong>:</p><ol><li><strong>Which frequency band</strong> to listen to</li><li><strong>At what time</strong> to be there</li></ol><p>A hostile radar might transmit on band 7 at time slot 1000, then band 15 at slot 1003, then band 3 at slot 1010. The receiver must be on the right band at the right time to intercept it.</p><h2 id="why-conventional-approaches-fail" tabindex="-1">Why conventional approaches fail <a class="header-anchor" href="#why-conventional-approaches-fail" aria-label="Permalink to &quot;Why conventional approaches fail&quot;">​</a></h2><h3 id="fixed-sequential-sweep" tabindex="-1">Fixed sequential sweep <a class="header-anchor" href="#fixed-sequential-sweep" aria-label="Permalink to &quot;Fixed sequential sweep&quot;">​</a></h3><p>Visit every band in a fixed order (1, 2, 3, ..., 24, 1, 2, 3...).</p><ul><li><strong>Problem:</strong> Wastes most dwell time on empty or unimportant bands. If a radar transmits 5% of the time, the sweep visits it only 5% as often as needed.</li></ul><h3 id="naive-adaptivity-camp-on-busy-band" tabindex="-1">Naive adaptivity (camp on busy band) <a class="header-anchor" href="#naive-adaptivity-camp-on-busy-band" aria-label="Permalink to &quot;Naive adaptivity (camp on busy band)&quot;">​</a></h3><p>Listen to whichever band had the most recent detections.</p><ul><li><strong>Problem:</strong> Misses most threats by ignoring the rest of the spectrum. Finds one emitter well but misses 46% of all threats (UCB bandit result).</li></ul><h3 id="the-tension" tabindex="-1">The tension <a class="header-anchor" href="#the-tension" aria-label="Permalink to &quot;The tension&quot;">​</a></h3><p>ASTRA resolves the fundamental tension: <strong>high reward</strong> (camp on productive bands) vs <strong>high coverage</strong> (sweep for new threats). No reference system achieves both simultaneously — SmartScan does.</p><h2 id="why-this-matters-for-defence" tabindex="-1">Why this matters for defence <a class="header-anchor" href="#why-this-matters-for-defence" aria-label="Permalink to &quot;Why this matters for defence&quot;">​</a></h2><p>In a real Electronic Warfare scenario:</p><ul><li>Hostile radars <strong>hop frequencies</strong> unpredictably</li><li>Some radars <strong>scan periodically</strong> (rotation, pulse repetition)</li><li>Some emitters are <strong>agile</strong> (frequency-hopping)</li><li>Some are <strong>stationary</strong> (continuous transmission)</li><li>New threats can appear at any time</li></ul><p>An ES receiver that wastes time on empty bands will miss critical threats. An ES receiver that camps on one band will miss everything else. <strong>ASTRA finds the optimal balance.</strong></p>`,22)])])}const u=a(i,[["render",r]]);export{m as __pageData,u as default};
